def copy_printouts(apps, schema_editor):
    """One field → rows. We do not touch files on disk: upload_to is the same,
    the field stores the path, so the row simply starts pointing to the same file."""
    ProductVariant = apps.get_model('catalog', 'ProductVariant')
    VariantPrintout = apps.get_model('catalog', 'VariantPrintout')
    rows = [
        VariantPrintout(variant_id=pk, file=name, sort_order=0)
        for pk, name in ProductVariant.objects.exclude(printout='')
                                              .exclude(printout__isnull=True)
                                              .values_list('pk', 'printout')
    ]
    VariantPrintout.objects.bulk_create(rows, batch_size=500)


def unlink_printouts(apps, schema_editor):
    """Reverse: the packaging's first sheet goes back into the field, the rest remain orphans
    (more than one will not fit in the field — we warn about this in the logs)."""
    ProductVariant = apps.get_model('catalog', 'ProductVariant')
    VariantPrintout = apps.get_model('catalog', 'VariantPrintout')
    seen = set()
    for pr in VariantPrintout.objects.order_by('variant_id', 'sort_order', 'pk'):
        if pr.variant_id in seen:
            continue
        seen.add(pr.variant_id)
        ProductVariant.objects.filter(pk=pr.variant_id).update(printout=pr.file)


